export function normalizeLife(v={}){const n=(x,d)=>Number.isFinite(x)?Math.max(0,Math.min(100,x)):d;return {food:n(v?.food,100),energy:n(v?.energy,100),groceries:Number.isInteger(v?.groceries)?Math.max(0,Math.min(20,v.groceries)):0}}
export function tickLife(life,dt,moving,running){const l=normalizeLife(life);dt=Math.max(0,Math.min(dt,.1));l.food=Math.max(0,l.food-dt*.018);l.energy=Math.max(0,l.energy-dt*(moving?(running?.045:.018):.004));return l}
export function lifeTransaction(state,action,place){const l=normalizeLife(state.life),s={...state,life:l};const fail=error=>({state:s,error});
 if(action==='groceries'){if(place!=='market')return fail('Visit the market cashier.');if(l.groceries>=20)return fail('Your bag is full.');if(s.cash<400)return fail('You need $4.00 for groceries.');return {state:{...s,cash:s.cash-400,life:{...l,groceries:l.groceries+1}},message:'Groceries packed · prepare a meal in your kitchen.'}}
 if(action==='meal'){if(place!=='cafe')return fail('Visit the café counter.');if(s.cash<600)return fail('You need $6.00 for lunch.');if(l.food>=100&&l.energy>=100)return fail('You are already full and rested.');return {state:{...s,cash:s.cash-600,life:{...l,food:Math.min(100,l.food+45),energy:Math.min(100,l.energy+15)}},message:'Lunch enjoyed · food +45, energy +15.'}}
 if(action==='cook'){if(place!=='home')return fail('Use your home kitchen.');if(!l.groceries)return fail('Buy groceries at the market first.');if(l.food>=100)return fail('You are already full.');return {state:{...s,life:{...l,groceries:l.groceries-1,food:Math.min(100,l.food+65)}},message:'Meal prepared · food +65.'}}
 return fail('Unknown action.');}
